window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ce7e5b119c6482b0"]={"versions": [{"id": "FIG-ce7e5b119c6482b0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Blockschaltbild / Interaktionsdiagramm im Kontext der modellbasierten Entwicklung (MBD) für AUTOSAR-Software-Komponenten (SW-C). Das Diagramm veranschaulicht auf methodischer Ebene die Trennung zwischen dem funktionalen Verhaltensmodell einer Software-Komponente und dessen Simulationsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus zwei zentralen rechteckigen Blöcken:</p>\n<ul class=\"fig-list\"><li><strong>Behavior Model of Software Component</strong>: Repräsentiert das interne funktionale Verhaltensmodell (z. B. Algorithmen, Zustandsautomaten oder Regelkreise) der AUTOSAR-Software-Komponente.\n</li><li><strong>Software Component Enviroment in order to simulate the software component</strong>: Repräsentiert die Simulations- und Testumgebung (Testbench / Plant-Modell / Restbus- bzw. Runtimesimulation), welche die Umgebungseinflüsse, Sensorik/Aktorik sowie die Laufzeitumgebung für die Komponente abbildet.\n</li><li><strong>Gerichtete Schnittstellenverbindungen</strong>:\n<ul class=\"fig-list\"><li>Rechter Pfad: Gerichteter Signal- bzw. Datenfluss vom Verhaltensmodell der SW-C zur Simulationsumgebung (Ausgangsgrößen, Aktoransteuerungen, Statuswerte).\n</li><li>Linker Pfad: Gerichteter Signal- bzw. Datenfluss von der Simulationsumgebung zurück in das Verhaltensmodell der SW-C (Eingangsgrößen, Sensorwerte, Trigger/Events).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Geschlossener Regel- bzw. Simulationskreis (Closed-Loop Simulation / Model-in-the-Loop):</p>\n<ol class=\"fig-list\"><li>Die Simulationsumgebung stellt Stimuli, Sensorsignale oder Rahmenbedingungen bereit und führt diese über den linken Signalpfad dem Verhaltensmodell der SW-C zu.\n</li><li>Das Verhaltensmodell verarbeitet die Eingangsdaten gemäß seiner internen Logik und berechnet Ergebnis- sowie Stellwerte.\n</li><li>Die Ausgangsdaten werden über den rechten Signalpfad an die Simulationsumgebung zurückübertragen.\n</li><li>Die Simulationsumgebung reagiert auf die neuen Ausgangswerte (z. B. Aktualisierung des Streckenmodells) und erzeugt die Stimuli für den nächsten Simulationsschritt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als konzeptionelle Richtlinie (Technical Report) für den modellbasierten Entwurfsprozess:</p>\n<ul class=\"fig-list\"><li>Es fordert die strikte Entkopplung von Verhaltensmodellierung der Kernfunktionalität und der sie umgebenden Simulationsinfrastruktur, um eine spätere automatische Codegenerierung und Integration in AUTOSAR-SWCs ohne Umgebungsartefakte zu gewährleisten.\n</li><li>Entwickler müssen sicherstellen, dass die Schnittstellen zwischen Verhaltensmodell und Umgebung den späteren AUTOSAR-Ports (Sender-Receiver, Client-Server) entsprechen und keine proprietären Simulationsspezifika in den Produktionscode einfließen.\n</li><li>Die Beschriftung enthält den typografischen Schreibfehler „Enviroment“ (statt „Environment“).\n</li></ul>"}, {"id": "FIG-56180afc28075162", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Blockschaltbild / Interaktionsdiagramm im Kontext der modellbasierten Entwicklung (MBD) für AUTOSAR-Software-Komponenten (SW-C). Das Diagramm veranschaulicht auf methodischer Ebene die Trennung zwischen dem funktionalen Verhaltensmodell einer Software-Komponente und dessen Simulationsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus zwei zentralen rechteckigen Blöcken:</p>\n<ul class=\"fig-list\"><li><strong>Behavior Model of Software Component</strong>: Repräsentiert das interne funktionale Verhaltensmodell (z. B. Algorithmen, Zustandsautomaten oder Regelkreise) der AUTOSAR-Software-Komponente.\n</li><li><strong>Software Component Enviroment in order to simulate the software component</strong>: Repräsentiert die Simulations- und Testumgebung (Testbench / Plant-Modell / Restbus- bzw. Runtimesimulation), welche die Umgebungseinflüsse, Sensorik/Aktorik sowie die Laufzeitumgebung für die Komponente abbildet.\n</li><li><strong>Gerichtete Schnittstellenverbindungen</strong>:\n<ul class=\"fig-list\"><li>Rechter Pfad: Gerichteter Signal- bzw. Datenfluss vom Verhaltensmodell der SW-C zur Simulationsumgebung (Ausgangsgrößen, Aktoransteuerungen, Statuswerte).\n</li><li>Linker Pfad: Gerichteter Signal- bzw. Datenfluss von der Simulationsumgebung zurück in das Verhaltensmodell der SW-C (Eingangsgrößen, Sensorwerte, Trigger/Events).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Geschlossener Regel- bzw. Simulationskreis (Closed-Loop Simulation / Model-in-the-Loop):</p>\n<ol class=\"fig-list\"><li>Die Simulationsumgebung stellt Stimuli, Sensorsignale oder Rahmenbedingungen bereit und führt diese über den linken Signalpfad dem Verhaltensmodell der SW-C zu.\n</li><li>Das Verhaltensmodell verarbeitet die Eingangsdaten gemäß seiner internen Logik und berechnet Ergebnis- sowie Stellwerte.\n</li><li>Die Ausgangsdaten werden über den rechten Signalpfad an die Simulationsumgebung zurückübertragen.\n</li><li>Die Simulationsumgebung reagiert auf die neuen Ausgangswerte (z. B. Aktualisierung des Streckenmodells) und erzeugt die Stimuli für den nächsten Simulationsschritt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als konzeptionelle Richtlinie (Technical Report) für den modellbasierten Entwurfsprozess:</p>\n<ul class=\"fig-list\"><li>Es fordert die strikte Entkopplung von Verhaltensmodellierung der Kernfunktionalität und der sie umgebenden Simulationsinfrastruktur, um eine spätere automatische Codegenerierung und Integration in AUTOSAR-SWCs ohne Umgebungsartefakte zu gewährleisten.\n</li><li>Entwickler müssen sicherstellen, dass die Schnittstellen zwischen Verhaltensmodell und Umgebung den späteren AUTOSAR-Ports (Sender-Receiver, Client-Server) entsprechen und keine proprietären Simulationsspezifika in den Produktionscode einfließen.\n</li><li>Die Beschriftung enthält den typografischen Schreibfehler „Enviroment“ (statt „Environment“).\n</li></ul>"}], "trans": [{"from": "FIG-ce7e5b119c6482b0", "to": "FIG-56180afc28075162", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
